/* @socom-skeleton body GetHandle__Q23zdb8CTexListFPCc */
namespace zdb {
CTexHandle* CTexList::GetHandle(const char* name)
	{
		for (auto i = begin(); i != end(); ++i)
		{
			CTexHandle* cur = *i;

			if (!cur->m_texture || !cur->m_name)
			{
				continue;
			}

			if (strcasecmp(cur->m_name, name) == 0)
				return cur;
		}

		return NULL;
	}
}

/* @socom-skeleton body Append__Q23zdb8CTexListFPQ23zdb8CTextureb */
namespace zdb {
CTexHandle* CTexList::Append(CTexture* texture, bool search)
	{
		CTexHandle* handle = NULL;

		if (search)
		{
			for (auto i = begin(); i != end(); i++)
			{
				CTexHandle* h = *i;

				if (h->m_texture == texture)
				{
					handle = h;
					break;
				}
			}
		}

		if (handle == NULL)
		{
			handle = CTexHandle::Create(texture);
			insert(begin(), handle);
		}

		return handle;
	}
}

/* @socom-skeleton stub Free__Q23zdb8CTexListFv */
void zdb::CTexList::Free()
{
	/* 0x2f87d0: destroy every handle (the last reference deletes its texture) and empty
	 * the list without releasing its storage */
	for (iterator it = begin(); it != end(); ++it)
	{
		CTexHandle::Destroy(*it);
		*it = NULL;
	}

	clear();
}
